            document.getElementById('recon-results').style.display = 'block';
            resetReconUI();

            if (result.status === 'completed') {
                const summary = `
                    <b>Target:</b> ${result.target}<br>
                    <b>Vulnerabilities Found:</b> ${result.total_vulnerabilities || 0}<br>
                    <b>Exploits Learned:</b> ${result.exploits_learned || 0}<br>
                    <b>Duration:</b> ${result.started_at} - ${result.completed_at}<br>
                `;
                document.getElementById('recon-summary').innerHTML = summary;

                // Log scan steps
                if (result.scans_completed) {
                    result.scans_completed.forEach(step => {
                        addChatMessage('HADES', step, 'ai');
                    });
                }

                addChatMessage('HADES', `✅ Scan complete! Found ${result.total_vulnerabilities || 0} potential issues.`, 'ai');
                refreshFindings();
            } else {
                document.getElementById('recon-summary').innerHTML = `<span style="color: #ff6b6b;">Error: ${result.error || 'Scan failed'}</span>`;
                addChatMessage('System', `Scan error: ${result.error}`, 'error');
            }
        }

        function resetReconUI() {
            document.getElementById('recon-btn').disabled = false;
            document.getElementById('recon-btn').textContent = '🚀 GO TO WORK';
        }

        // ========== PDF EXPORT FUNCTIONS ==========
        function exportToPDF(clearAfter) {
            document.getElementById('export-status').innerHTML = '<span style="color: #ffa500;">⏳ Generating PDF...</span>';

            if (socket.readyState === WebSocket.OPEN) {
                socket.send(JSON.stringify({ command: 'hades_export_pdf', clear_after: clearAfter }));
            } else {
                fetch('/hades/export-pdf', {
                    method: 'POST',
                    headers: {'Content-Type': 'application/json'},
                    body: JSON.stringify({ clear_after: clearAfter })
                })
                .then(r => r.json())
                .then(data => handlePDFExport(data))
                .catch(err => {
                    document.getElementById('export-status').innerHTML = `<span style="color: #ff6b6b;">Error: ${err}</span>`;
                });
            }
        }

        function handlePDFExport(data) {
            if (data.status === 'success' || data.filename) {
                const filename = data.filename;
                const downloadUrl = data.download_url;

                document.getElementById('export-status').innerHTML = `
                    <span style="color: #00ff00;">✅ PDF Generated!</span><br>
                    <a href="${downloadUrl}" target="_blank" style="color: #00fff2;">📥 Download: ${filename}</a>
                    <br>Exploits: ${data.exploits || 0} | Findings: ${data.findings || 0}
                    ${data.cleared ? '<br><span style="color: #ffa500;">Data cleared after export</span>' : ''}
                `;

                addChatMessage('HADES', `📄 PDF Report generated: ${filename}`, 'ai');
                refreshReports();

                if (data.cleared) {
                    refreshFindings();
                }
            } else {
                document.getElementById('export-status').innerHTML = `<span style="color: #ff6b6b;">Error: ${data.message || 'Export failed'}</span>`;
            }
        }

        function refreshReports() {
            fetch('/hades/reports')
                .then(r => r.json())
                .then(data => {
                    const list = document.getElementById('reports-list');
                    if (data.reports && data.reports.length > 0) {
                        list.innerHTML = data.reports.slice(0, 5).map(r => 
                            `<div style="padding: 3px; border-bottom: 1px solid #333;">
                                <a href="${r.download_url}" target="_blank" style="color: #00fff2;">${r.filename}</a>
                                <span style="color: #666;"> (${(r.size/1024).toFixed(1)}KB)</span>
                            </div>`
                        ).join('');
                    } else {
                        list.innerHTML = '<div style="color: #666;">No reports yet</div>';
                    }
                });
        }

        // Load reports on page load
        document.addEventListener('DOMContentLoaded', function() {
            refreshReports();
        });
    </script>
</body>

</html>

