socket.onmessage = (event) => {
    const data = JSON.parse(event.data);
    console.log('📨 Received:', data.type);

    if (data.type === 'chat_response') {
        addChatMessage('HADES', data.data.response, 'ai');
        if (data.data.action) {
            console.log('Action suggested:', data.data.action);
        }
    } else if (data.type === 'chat_error') {
        addChatMessage('System', `Error: ${data.data.error}`, 'error');
    } else if (data.type === 'ai_started') {
        addChatMessage('System', `HADES AI engine online! (${data.data.engine || 'HadesAI'})`, 'system');
        addChatMessage('HADES', data.data.test_response, 'ai');
    } else if (data.type === 'ai_error') {
        addChatMessage('System', `HADES startup error: ${data.data.message}`, 'error');
    } else if (data.type === 'tool_result') {
        addChatMessage('HADES', `Tool result: ${JSON.stringify(data.data.response || data.data)}`, 'ai');
    } else if (data.type === 'learn_result') {
        addChatMessage('HADES', `Learned ${data.data.exploits_learned || 0} exploits from URL`, 'ai');
    } else if (data.type === 'scan_started') {
        addChatMessage('System', data.data.message || 'Scan initiated...', 'system');
    } else if (data.type === 'full_scan_result') {
        // Handle full site scan result
        if (typeof handleFullScanResult === 'function') {
            handleFullScanResult(data.data);
        } else {
            addChatMessage('HADES', `Scan complete: ${data.data.total_vulnerabilities || 0} vulnerabilities found`, 'ai');
        }
    } else if (data.type === 'pdf_exported') {
        // Handle PDF export result
        if (typeof handlePDFExport === 'function') {
            handlePDFExport(data.data);
        } else {
            addChatMessage('HADES', `PDF exported: ${data.data.filename}`, 'ai');
        }
    } else if (data.type === 'module_executed') {
        if (data.data.status === 'success') {
            addChatMessage('System', `Module ${data.data.module_name || 'unknown'} executed successfully`, 'system');
        } else {
            addChatMessage('System', `Module error: ${data.data.message}`, 'error');
        }
    } else if (data.type === 'metrics_update') {
        updateMetrics(data);
    } else {
        updateModuleStatus(data);
    }
};

